def maxrect_within(mask):
    # mask: boolean array of comp cells; find largest rectangular all-true subregion
    H,W=mask.shape
    best=(0,None)
    # histogram-based largest rectangle in binary matrix
    heights=np.zeros((H+1,W),int)
    for i in range(H):
        for j in range(W):
            if mask[i,j]: heights[i+1,j]=heights[i,j]+1
        for j in range(W):
            stack=[]
            for k in range(j+1):
                hh=heights[i+1,k]
                start=k
                while stack and heights[i+1,stack[-1]]>=hh:
                    start=stack.pop()
                area=hh*(k-start+1)
                if area>best[0]: best=(area,(i+1,start,j,k))
                stack.append(k)
    return best
