    # recolor the per-color max-area solid rects of colors 1,2,3,6,8 (exclude color 0); set those cells to 4
    H=len(gi);W=len(gi[0]);go=[row[:] for row in gi]
    pmax=per_color_max(gi)
    for c,(a,r0,c0,h,w) in pmax.items():
        if a>=9 and c!=0:
            for r in range(r0,r0+h):
                for cc in range(c0,c0+w): go[r][cc]=4
    return go
